attribute vec3 aO; attribute vec4 aS, aD; attribute float aT; attribute vec3 bary; uniform float uTime; varying vec3 vN, vV, vB; varying vec2 vQ; varying float vH;
    void main(){
      float u = uTime - aT - aD.x; if (u < 0. || u > 1.05){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = clamp(u/.12, 0., 1.), rise = 1. - pow(1. - k, 3.), sink = smoothstep(1.12,1.55,u);
      vec3 sc = vec3(aS.x, aS.y, aS.x);
      vec3 p = position*sc, n = normalize(normal/sc);
      float cy = cos(aS.z), sy = sin(aS.z); p = vec3(cy*p.x - sy*p.z, p.y, sy*p.x + cy*p.z); n = vec3(cy*n.x - sy*n.z, n.y, sy*n.x + cy*n.z);
      float ct = cos(aS.w), st = sin(aS.w); vec3 ax = vec3(cos(aD.y), 0., sin(aD.y));   // lean about a horizontal axis
      p = p*ct + cross(ax, p)*st + ax*dot(ax, p)*(1. - ct); n = n*ct + cross(ax, n)*st + ax*dot(ax, n)*(1. - ct);
      vec3 W = aO + p - vec3(0., ((1. - rise) + sink)*aS.y*1.05, 0.);                 // erupts out of the ground, sinks back into it
      vN = n; vV = normalize(cameraPosition - W); vB = bary; vH = position.y; vQ = vec2((position.x - position.z)*aS.x + aD.z*9., position.y*aS.y);
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.);
    }

layers.fragment:
uniform vec3 uMoon; varying vec3 vN, vV, vB; varying vec2 vQ; varying float vH; 
  uniform sampler2D uBG; uniform vec2 uRes;
  float ih(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7)))*43758.5453); }
  float ivn(vec2 p){ vec2 i = floor(p), f = fract(p); f = f*f*(3. - 2.*f);
    return mix(mix(ih(i), ih(i + vec2(1., 0.)), f.x), mix(ih(i + vec2(0., 1.)), ih(i + vec2(1., 1.)), f.x), f.y); }
  float ivn3(vec3 p){ return mix(ivn(p.xy + floor(p.z)*17.13), ivn(p.xy + (floor(p.z) + 1.)*17.13), smoothstep(0., 1., fract(p.z))); }
  /* n: facet normal (world, facing the camera) · V: to camera · B: unused · h: 0 base → 1 point · q: coords on the crystal
     (x across, y along) · L: key light. Opaque output: the background comes in through the refraction. */
  vec4 iceShade(vec3 n,vec3 V,vec3 B,float h,vec2 q,vec3 L){
 n=dot(n,V)<0.?-n:n;float nv=clamp(dot(n,V),0.,1.),fr=.028+.972*pow(1.-nv,5.);
 vec3 R=reflect(-V,n);float spec=pow(max(dot(R,normalize(L)),0.),90.)*1.9+pow(max(dot(R,normalize(V+vec3(-.3,.55,.2))),0.),65.)*.65;
 float thick=(.3+.7*nv)*(1.-.65*clamp(h,0.,1.));float cloud=ivn(q*1.6+vec2(4.7))*.8+ivn(q*3.1)*.2;
 float frost=smoothstep(.64,.88,cloud)*thick,crack=pow(1.-abs(fract(q.y*1.7+q.x*.9)-.5)*2.,55.)*.10*thick;
 vec3 vn=(viewMatrix*vec4(n,0.)).xyz;vec2 suv=gl_FragCoord.xy/uRes;
 vec3 bg=texture2D(uBG,suv-vn.xy*.014*thick).rgb;
 vec3 glass=mix(vec3(.62,.82,.91),vec3(.18,.43,.57),thick);
 vec3 col=bg*glass*.40+glass*(.38+.16*fr)+vec3(.72,.86,.94)*(frost*.25+crack)+vec3(.95,.98,1.)*spec;
 float opacity=clamp(.36+.44*thick+.12*frost+spec*.08,.34,.94);
 return vec4(col,opacity); }
    void main(){ gl_FragColor = iceShade(normalize(vN), normalize(vV), vB, vH, vQ, uMoon); }

layers.vertex:
attribute vec3 aO;attribute float aT;attribute vec4 aP;uniform float uTime;varying vec2 vQ;varying float vU,vSeed;
void main(){float u=uTime-aT;if(u<0.||u>1.7){gl_Position=vec4(2.,2.,2.,1.);return;}
vec2 q=position.xy;float c=cos(aP.y),s=sin(aP.y);vec2 p=mat2(c,-s,s,c)*q*aP.x;
vec3 P=aO+vec3(p.x,.07+aP.z+.025*sin(p.x*2.+p.y*1.7-u*.8+aP.w),p.y);
vQ=q;vU=u;vSeed=aP.w;gl_Position=projectionMatrix*viewMatrix*vec4(P,1.);}

layers.fragment:
varying vec2 vQ;varying float vU,vSeed;
float sh(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5);}
float sn(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(sh(i),sh(i+vec2(1.,0.)),f.x),mix(sh(i+vec2(0.,1.)),sh(i+vec2(1.,1.)),f.x),f.y);}
void main(){float edge=smoothstep(.98,.52,length(vQ)),f=smoothstep(0.,.15,vU)*(1.-smoothstep(1.18,1.7,vU));
vec2 flow=vQ*2.3+vec2(vU*.17+vSeed,vU*.09-vSeed);float n=sn(flow)*.72+sn(flow*2.4)*.28;
float cloud=smoothstep(.23,.75,n),alpha=edge*f*(.035+.11*cloud);
gl_FragColor=vec4(vec3(.72,.77,.81),alpha);}
